edits.newText:
if (path.startsWith('/projects/')) {
  const id = decodeURIComponent(path.slice('/projects/'.length));
  const project = projects.find(item => String(item.id) === id);
  app.innerHTML = `<button type="button" id="back">Projects</button><h1>${project ? escapeHtml(project.name) : 'Project not found'}</h1>${project ? `<form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"><button type="submit">Create task</button></form><p id="alert" role="alert" aria-live="polite"></p><label>Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label><section id="tasks" aria-label="Tasks"></section>` : ''}`;
  document.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
  if (project) {
    const endpoint = `/api/projects/${encodeURIComponent(id)}/tasks`;
    const tasks = await fetch(endpoint).then(r => r.json());
    const list = document.querySelector('#tasks');
    const alert = document.querySelector('#alert');
    function renderTasks() {
      const filter = document.querySelector('#task-filter').value;
      list.innerHTML = tasks.filter(task => filter === 'All' || (filter === 'Completed') === task.completed).map(task => `<div class="task-row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''} data-id="${task.id}"></div>`).join('');
      list.querySelectorAll('input').forEach(input => input.addEventListener('change', async () => {
        const task = tasks.find(item => String(item.id) === input.dataset.id);
        const response = await fetch(`${endpoint}/${input.dataset.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: input.checked }) });
        if (response.ok) { task.completed = input.checked; renderTasks(); }
      }));
    }
    renderTasks();
    document.querySelector('#task-filter').addEventListener('change', renderTasks);
    document.querySelector('#task-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#task-title');
      const title = input.value.trim();
      if (!title) { alert.textContent = 'Task title is required'; return; }
      const response = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
      if (!response.ok) { alert.textContent = 'Task title is required'; return; }
      tasks.push(await response.json());
      input.value = ''; alert.textContent = ''; renderTasks();
    });
  }

